pattern:
set -eu git diff --cached --name-only git show ":$f" python3 ~/dotfiles/tools/garbage-guard/guard.py check-text echo "GG_FAIL $f" exit 1 echo GARbage_GUARD_OK python3 - <<'EOF'
import re,pathlib
try:
    import yaml
except ImportError:
    yaml=None
for f in ['opencode-global/.config/opencode/agent/reviewer.md','opencode-global/.config/opencode/agent/verifier.md','opencode-global/.config/opencode/agent/meta.md']:
    t=pathlib.Path(f).read_text()
    m=re.match(r'^---\n(.*?)\n---\n',t,re.S)
    assert m, f'no frontmatter {f}'
    if yaml:
        yaml.safe_load(m.group(1))
        print('YAML_OK',f)
    else:
        print('YAML_SKIPPED(no pyyaml)',f)
EOF git diff --cached sha256sum git status --short
